   221→    // Serializes the TxType to the buffer if necessary, returning 2 bits of the type as an
   222→    // identifier instead of the length.
   223→    fn to_compact<B>(&self, buf: &mut B) -> usize
   224→    where
   225→        B: alloy_rlp::bytes::BufMut + AsMut<[u8]>,
   226→    {
   227→        let identifier = self.tx_type().to_compact(buf);
   228→        delegate!(self => tx.to_compact(buf));
   229→        identifier
   230→    }
   231→
   232→    // For backwards compatibility purposes, only 2 bits of the type are encoded in the identifier
   233→    // parameter. In the case of a [`COMPACT_EXTENDED_IDENTIFIER_FLAG`], the full transaction type
   234→    // is read from the buffer as a single byte.
   235→    //
   236→    // # Panics
   237→    //
   238→    // A panic will be triggered if an identifier larger than 3 is passed from the database. For
   239→    // optimism a identifier with value [`DEPOSIT_TX_TYPE_ID`] is allowed.
   240→    fn from_compact(buf: &[u8], identifier: usize) -> (Self, &[u8]) {
   241→        let (tx_type, buf) = TxType::from_compact(buf, identifier);
   242→
   243→        match tx_type {
   244→            TxType::Legacy => {
   245→                let (tx, buf) = TxLegacy::from_compact(buf, buf.len());
   246→                (Self::Legacy(tx), buf)
   247→            }
   248→            TxType::Eip2930 => {
   249→                let (tx, buf) = TxEip2930::from_compact(buf, buf.len());
   250→                (Self::Eip2930(tx), buf)
   251→            }
   252→            TxType::Eip1559 => {
   253→                let (tx, buf) = TxEip1559::from_compact(buf, buf.len());
   254→                (Self::Eip1559(tx), buf)
   255→            }
   256→            TxType::Eip4844 => {
   257→                let (tx, buf) = TxEip4844::from_compact(buf, buf.len());
   258→                (Self::Eip4844(tx), buf)
   259→            }
   260→            TxType::Eip7702 => {
   261→                let (tx, buf) = TxEip7702::from_compact(buf, buf.len());
   262→                (Self::Eip7702(tx), buf)
   263→            }
   264→        }
   265→    }
   266→}
