      "code_excerpt": "// PRIMARY: crates/ethereum/payload/src/validator.rs:ensure_well_formed_payload (lines 66-107)\npub fn ensure_well_formed_payload<ChainSpec, T>(chain_spec: ChainSpec, payload: ExecutionData) -> Result<SealedBlock<Block<T>>, PayloadError>\nwhere ChainSpec: EthereumHardforks, T: SignedTransaction,\n{\n    let ExecutionData { payload, sidecar } = payload;\n    let expected_hash = payload.block_hash();\n    let sealed_block = payload.try_into_block_with_sidecar(&sidecar)?.seal_slow();\n    if expected_hash != sealed_block.hash() {\n        return Err(PayloadError::BlockHash { execution: sealed_block.hash(), consensus: expected_hash })\n    }\n    shanghai::ensure_well_formed_fields(sealed_block.body(), chain_spec.is_shanghai_active_at_timestamp(sealed_block.timestamp))?;\n    cancun::ensure_well_formed_fields(&sealed_block, sidecar.cancun(), chain_spec.is_cancun_active_at_timestamp(sealed_block.timestamp))?;\n    prague::ensure_well_formed_fields(sealed_block.body(), sidecar.prague(), chain_spec.is_prague_active_at_timestamp(sealed_block.timestamp))?;\n    Ok(sealed_block)\n}\n// CALLER: crates/ethereum/node/src/engine.rs:EthereumEngineValidator (lines 46-52)\nfn ensure_well_formed_payload(&self, payload: ExecutionData) -> Result<RecoveredBlock<Self::Block>, NewPayloadError> {\n    let sealed_block = self.inner.ensure_well_formed_payload(payload)?;\n    sealed_block.try_recover().map_err(|e| NewPayloadError::Other(e.into()))\n}"
